WITH inner_cte AS ( SELECT sd.DEPARTMENT_NAME, MAX(tso.NUM_ENROLLED_STUDENTS) - MIN(tso.NUM_ENROLLED_STUDENTS) AS enrolled_range, VARIANCE(tso.NUM_ENROLLED_STUDENTS) AS enrolled_variance FROM TIP_SUBJECT_OFFERED tso JOIN SIS_DEPARTMENT sd ON tso.OFFER_DEPT_CODE = sd.DEPARTMENT_CODE JOIN SIS_COURSE_DESCRIPTION scd ON sd.DEPARTMENT_CODE = scd.DEPARTMENT WHERE sd.IS_DEGREE_GRANTING = 'Y' AND scd.COURSE_LEVEL = 'G' GROUP BY sd.DEPARTMENT_NAME ORDER BY enrolled_range DESC ), DeptSubjectMaterialStats AS ( SELECT tso.OFFER_DEPT_NAME, tso.OFFER_SCHOOL_NAME, COUNT(DISTINCT tso.SUBJECT_ID) AS subject_count, MIN(td.ISBN) AS min_isbn, AVG(tso.NUM_ENROLLED_STUDENTS) AS avg_enrolled_students FROM TIP_SUBJECT_OFFERED tso JOIN TIP_DETAIL td ON tso.SUBJECT_ID = td.SUBJECT_ID WHERE tso.NUM_ENROLLED_STUDENTS > 2 GROUP BY tso.OFFER_DEPT_NAME, tso.OFFER_SCHOOL_NAME ) SELECT inner_cte.DEPARTMENT_NAME, inner_cte.enrolled_range, inner_cte.enrolled_variance, dsm.subject_count, dsm.min_isbn, dsm.avg_enrolled_students FROM inner_cte JOIN DeptSubjectMaterialStats dsm ON inner_cte.DEPARTMENT_NAME = dsm.OFFER_DEPT_NAME ORDER BY inner_cte.enrolled_range DESC;